#!/usr/bin/env python3
import sys, os, re, json, gzip, csv, io, datetime
import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation

KG = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
      'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        enc = 'utf-8'; b = b[3:]
    elif b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        enc = 'utf-16'
    else:
        enc = 'utf-8'
        m = re.search(rb'^#\s*charset:\s*([\w.\-]+)', b[:2000], re.M)
        if m:
            enc = m.group(1).decode('ascii')
    t = b.decode(enc, errors='replace') if enc != 'utf-16' else b.decode('utf-16')
    return t.replace('\r\n', '\n')


def norm_id(s):
    m = re.search(r'(\d+)', s or '')
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def num(s, dec_comma=False):
    s = s.strip()
    if dec_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def parse_date(s, form):
    s = s.strip()
    if not s:
        return None
    # full timestamps
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?$', s)
    if m:
        y, mo, d, h, mi, se, tz = m.groups()
        dt = datetime.datetime(int(y), int(mo), int(d), int(h), int(mi), int(se or 0))
        if tz and tz != 'Z':
            sign = 1 if tz[0] == '+' else -1
            tzd = tz[1:].replace(':', '')
            dt -= sign * datetime.timedelta(hours=int(tzd[:2]), minutes=int(tzd[2:]))
        return dt.date()
    form = (form or 'iso')
    fu = form.upper()
    if fu in ('ISO', 'YMD'):
        y, mo, d = map(int, re.split(r'[-/]', s)[:3])
    elif fu in ('DMY', 'DD/MM/YYYY', 'DD.MM.YYYY'):
        d, mo, y = map(int, re.split(r'[-/.]', s)[:3])
    elif fu == 'MM/DD/YYYY':
        mo, d, y = map(int, re.split(r'[-/]', s)[:3])
    elif fu == 'SERIAL':
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(Decimal(s)))
    elif fu == 'YYYYMMDD':
        y, mo, d = int(s[:4]), int(s[4:6]), int(s[6:8])
    elif fu == 'YYYYDDD':
        return datetime.date(int(s[:4]), 1, 1) + datetime.timedelta(days=int(s[4:7]) - 1)
    elif re.match(r'^\d{1,2} [A-Za-z]{3} \d{4}$', s):
        return datetime.datetime.strptime(s, '%d %b %Y').date()
    else:
        raise ValueError('date form ' + form)
    return datetime.date(y, mo, d)


# record: dict(id, type in N/C/V, date, kg(Decimal), status)

def logical_lines(text):
    """Yield ('comment', line) or ('row', raw_text) with quote-aware joining."""
    lines = text.split('\n')
    i = 0
    while i < len(lines):
        l = lines[i]
        i += 1
        if l.strip() == '' :
            continue
        if l.startswith('#'):
            yield ('comment', l)
            continue
        buf = l
        while buf.count('"') % 2 == 1 and i < len(lines):
            buf += '\n' + lines[i]
            i += 1
        yield ('row', buf)


def split_row(raw, delim, quoted):
    if quoted:
        return next(csv.reader([raw], delimiter=delim, quotechar='"'))
    return raw.split(delim)


def parse_delimited(text, depot, delim, quoted, cols, base_date, base_unit, dec_comma):
    seq = None
    date_form = base_date
    unit = base_unit
    dcomma = dec_comma
    header = None
    recs = []
    colset = set(cols)
    for kind, raw in logical_lines(text):
        if kind == 'comment':
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*?)\s*$', raw)
            if depot == 'harbor':
                m2 = re.search(r'seq=(\d+)', raw)
                if m2:
                    seq = int(m2.group(1))
            if m:
                name = m.group(1).strip().lower(); val = m.group(2)
                if name == 'seq':
                    seq = int(val)
                elif name in ('unit', 'weight unit'):
                    mu = re.match(r'(kg|g|lb|oz)\b', val.strip().lower())
                    if mu:
                        unit = mu.group(1)
                    if 'decimal comma' in val.lower():
                        dcomma = True
                elif name in ('dates', 'date format'):
                    date_form = val.strip()
            continue
        f = split_row(raw, delim, quoted)
        if f and all(x.strip() in colset for x in f) and len(f) > 1:
            header = [x.strip() for x in f]
            continue
        if header is None:
            continue
        if any(x.strip().upper() == 'TOTAL' for x in f):
            continue
        row_unit = None
        if len(f) > len(header):
            # row carries its own unit: find it
            extra = f[len(header):]
            f = f[:len(header)]
            for x in extra:
                if x.strip().lower() in KG:
                    row_unit = x.strip().lower()
        if len(f) < len(header):
            f = f + [''] * (len(header) - len(f))
        r = dict(zip(header, f))
        recs.append((r, unit, row_unit, date_form, dcomma))
    return seq, recs


def mk(id_, typ, date, kg, status):
    return {'n': norm_id(id_), 'type': typ, 'date': date, 'kg': kg, 'status': norm_status(status)}


def weight_with_unit(s, default_unit, dcomma, row_unit=None):
    s = s.strip()
    m = re.match(r'^([\d.,]+)\s*([A-Za-z]+)$', s)
    if m:
        return num(m.group(1), dcomma) * KG[m.group(2).lower()]
    return num(s, dcomma) * KG[row_unit or default_unit]


def do_east(text):
    seq, rows = parse_delimited(text, 'east', ',', True,
        ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'], 'YMD', 'kg', False)
    out = []
    for r, unit, ru, df, dc in rows:
        t = {'N': 'N', 'C': 'C', 'V': 'V'}[r['type'].strip().upper() or 'N']
        if t == 'V':
            out.append(mk(r['id'], 'V', None, None, '')); continue
        out.append(mk(r['id'], t, parse_date(r['shipped'], df),
                      weight_with_unit(r['gross'], unit, dc, ru), r['status']))
    return seq, out


def do_harbor(text):
    seq, rows = parse_delimited(text, 'harbor', '|', False,
        ['rec', 'ref', 'date', 'weight', 'state'], 'iso', 'kg', False)
    st = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
    out = []
    for r, unit, ru, df, dc in rows:
        t = {'NEW': 'N', 'COR': 'C', 'VOID': 'V'}[r['rec'].strip().upper()]
        if t == 'V':
            out.append(mk(r['ref'], 'V', None, None, '')); continue
        s = r['state'].strip().upper()
        out.append(mk(r['ref'], t, parse_date(r['date'], df),
                      weight_with_unit(r['weight'], unit, dc, ru), st.get(s, s)))
    return seq, out


def do_lakeside(text):
    seq, rows = parse_delimited(text, 'lakeside', ',', True,
        ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'], 'iso', 'kg', False)
    out = []
    for r, unit, ru, df, dc in rows:
        k = r['kind'].strip().lower()
        t = {'': 'N', 'new': 'N', 'corr': 'C', 'void': 'V'}[k]
        if t == 'V':
            out.append(mk(r['id'], 'V', None, None, '')); continue
        out.append(mk(r['id'], t, parse_date(r['shipped'], df),
                      num(r['gross_kg'], dc) * KG['kg'], r['status']))
    return seq, out


def do_river(text):
    seq, rows = parse_delimited(text, 'river', '\t', False,
        ['t', 'ref', 'shipped', 'weight', 'status'], 'MM/DD/YYYY', 'kg', False)
    out = []
    for r, unit, ru, df, dc in rows:
        t = {'': 'N', 'C': 'C', 'V': 'V'}[r['t'].strip().upper()]
        if t == 'V':
            out.append(mk(r['ref'], 'V', None, None, '')); continue
        out.append(mk(r['ref'], t, parse_date(r['shipped'], df),
                      weight_with_unit(r['weight'], unit, dc, ru), r['status']))
    return seq, out


def do_west(text):
    seq, rows = parse_delimited(text, 'west', ';', False,
        ['id', 'typ', 'shipped', 'weight', 'status', 'note'], 'DD.MM.YYYY', 'kg', True)
    out = []
    for r, unit, ru, df, dc in rows:
        t = {'': 'N', 'N': 'N', 'C': 'C', 'V': 'V'}[r['typ'].strip().upper()]
        if t == 'V':
            out.append(mk(r['id'], 'V', None, None, '')); continue
        d = parse_date(r['shipped'], 'DD.MM.YYYY' if not re.search(r'[-/]', r['shipped']) or '.' in r['shipped'] else df)
        out.append(mk(r['id'], t, d, weight_with_unit(r['weight'], unit, True, ru), r['status']))
    return seq, out


def do_north(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            k = (o.get('kind') or 'new').lower()
            t = {'new': 'N', 'amend': 'C', 'void': 'V'}[k]
            if t == 'V':
                out.append(mk(o['id'], 'V', None, None, '')); continue
            kg = None
            for key, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', key)
                if m:
                    kg = Decimal(str(val)) * KG[m.group(1)]
            out.append(mk(o['id'], t, parse_date(o['shipped_at'], 'iso'), kg, o['status']))
    return seq, out


def do_central(text):
    text = re.sub(r'^<\?xml[^>]*\?>', '', text.lstrip())
    root = ET.fromstring(text)
    seq = int(root.get('seq'))
    ru = (root.get('weight-unit') or 'kg').lower()
    out = []
    for e in root.iter('shipment'):
        t = {'': 'N', 'new': 'N', 'correction': 'C', 'void': 'V'}[(e.get('type') or '').lower()]
        if t == 'V':
            out.append(mk(e.get('id'), 'V', None, None, '')); continue
        w = e.find('weight')
        unit = (w.get('unit') or ru).lower()
        kg = Decimal(w.text.strip().replace(',', '')) * KG[unit]
        sh = e.get('shipped')
        c = e.find('shipped')
        if c is not None and c.text:
            sh = c.text.strip()
        d = parse_date(sh, 'iso') if re.match(r'^\d{4}-', sh) else \
            datetime.datetime.strptime(sh, '%d %b %Y').date()
        out.append(mk(e.get('id'), t, d, kg, e.findtext('status') or ''))
    return seq, out


LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26), sf='YYYYDDD', wu='g', scale=Decimal(1)),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), ship=(10, 18), w=(18, 26), st=(26, 27), sf='YYYYMMDD', wu='kg', scale=Decimal('0.01')),
    'FW3': dict(len=41, id=(0, 9), ship=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25), sf='YYYYDDD', wu='lb', scale=Decimal('0.1')),
}


def do_south(text):
    seq = None
    layout = None
    out = []
    stc = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
    bylen = {v['len']: k for k, v in LAYOUTS.items()}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.startswith('\f') or 'SHIPMENT LISTING' in line:
            continue
        if line.strip() == '':
            continue
        if line.startswith('#LAYOUT'):
            layout = line.split()[1].strip(); continue
        if line.startswith('#SEQ'):
            seq = int(line.split()[1]); continue
        if line.startswith('#END') or line.startswith('#'):
            continue
        name = bylen.get(len(line), layout)
        if len(line) != LAYOUTS[name]['len'] and len(line.rstrip()) <= LAYOUTS[name]['len']:
            line = line.ljust(LAYOUTS[name]['len'])
            if layout in LAYOUTS and name == layout: pass
        L = LAYOUTS[name]
        g = lambda k: line[L[k][0]:L[k][1]]
        t = g('type').strip().upper()
        if t == 'V':
            out.append(mk(g('id'), 'V', None, None, '')); continue
        d = parse_date(g('ship'), L['sf'])
        kg = Decimal(int(g('w'))) * L['scale'] * KG[L['wu']]
        out.append(mk(g('id'), t, d, kg, stc[g('st').strip().upper()]))
    return seq, out


HANDLERS = {'central': do_central, 'east': do_east, 'harbor': do_harbor,
            'lakeside': do_lakeside, 'north': do_north, 'river': do_river,
            'south': do_south, 'west': do_west}


def main():
    data, outf = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data)):
        p = os.path.join(data, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        if depot not in HANDLERS:
            continue
        seq, recs = HANDLERS[depot](read_text(p))
        exports[depot].append((seq if seq is not None else 0, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        lst.sort(key=lambda x: (x[0], x[1]))
        for seq, name, recs in lst:
            for r in recs:
                n = r['n']
                if r['type'] == 'N':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'C':
                    cur[n] = r; corrections += 1
                else:
                    cur.pop(n, None); corrections += 1
        current[depot] = cur
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    handovers = 0
    owners = {}
    for d in current:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: ORDER.index(x) if x in ORDER else 99)
        r = current[d][n]
        if r['status'] in ('delivered', 'delivered_late'):
            depots[d][0] += 1; depots[d][1] += r['kg']
            k = r['date'].strftime('%Y-%m')
            m = months.setdefault(k, [0, Decimal(0)])
            m[0] += 1; m[1] += r['kg']
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': float(round(v[1], 2))} for d, v in sorted(depots.items())},
        'months': {k: {'shipments': v[0], 'total_kg': float(round(v[1], 2))} for k, v in sorted(months.items())},
        'corrections_applied': corrections, 'resends_dropped': resends, 'handovers': handovers}
    with open(outf, 'w') as f:
        json.dump(res, f, indent=2)


main()
